import './neon-chip-select-field.scss';
import { createElement, updateDynamicText, updateDynamicAttribute, dynamicAttr, elementIsDisabled, getClosest, replace } from '../shared/dom-manipulation';
import { addTranslationListener } from '@ps-refarch-ux/mfe-utils';
import { getRequiredOnlyValidators } from '../shared/validation-engine/validate-engine';
import { AbstractInputField } from '../shared/abstract-input-field';
export class NeonChipSelectField extends AbstractInputField {
    static get observedAttributes() {
        return super.observedAttributes.concat([
            'data-single-select'
        ]);
    }
    set options(value) {
        if (value instanceof Array) {
            value = value.filter((option) => {
                const isValidValue = option.name != null && option.name.length > 0;
                if (!isValidValue) {
                    console.error('An array option was removed because the name = \'\'');
                }
                return isValidValue;
            });
        }
        //We need to check to see if the new array of options has the same value as
        //What's currently here.  If everything is the same, then there will be no reason to redraw the checkboxes.
        let isDifferent = false;
        if (this.options != null && value != null && this.options.length === value.length) {
            for (let i = 0; i < this.options.length; i++) {
                const newCheckOption = value[i];
                const oldCheckOption = this.options[i];
                if (oldCheckOption.id !== newCheckOption.id ||
                    oldCheckOption.labelText !== newCheckOption.labelText ||
                    oldCheckOption.name !== newCheckOption.name ||
                    oldCheckOption.disabled !== newCheckOption.disabled ||
                    oldCheckOption.dataTooltipPlacement !== newCheckOption.dataTooltipPlacement ||
                    oldCheckOption.dataTooltipText !== newCheckOption.dataTooltipText) {
                    isDifferent = true;
                    break; //Once we know it's different, we don't have to keep checking
                }
            }
        }
        else {
            isDifferent = true;
        }
        this._options = value;
        if (isDifferent) {
            this.redrawChips();
            if (this.runValidationOnceOptionsSet) {
                this.validateWidget();
                this.runValidationOnceOptionsSet = false;
            }
        }
    }
    get options() {
        return this._options;
    }
    constructor() {
        super();
        this.widgetTag = 'neon-chip-select-field';
        //neon-chip-select-single
        this.isUsesLabel = false;
        this.isUsesLegend = true; // This is set to true because the legend is used as the label for the field.
        // Prevents race condition to prevent the validation appearing
        // after modelValue getting set before the options are set.
        this.runValidationOnceOptionsSet = false;
        //TODO: This component was created by the create-component script.
        //Please delete the references to the attribute "id" in this file if
        //your element has no clickable items created.
        this.isIdRequired = true;
        this.isUsesLabel = false;
    }
    generateValidationRules() {
        this.validators = getRequiredOnlyValidators(this.getAttribute('data-is-required') === 'true');
        this.addCustomValidateToValidators();
    }
    renderInputElement() {
        return createElement('div');
    }
    validateModelValueType(modelValue) {
        if (typeof modelValue === 'string' && modelValue.length > 0) {
            return modelValue;
        }
        return undefined;
    }
    setModelValue(modelValue, skip) {
        if ((this.modelValue == null) && (modelValue == null)) {
            return false;
        }
        if (modelValue !== this._modelValue) {
            this._modelValue = modelValue;
            if (skip !== true) {
                this.setValue(this.modelValue);
            }
            return true;
        }
        return false;
    }
    setValue(value, skip) {
        const inputEls = this.querySelectorAll('neon-2_20_1-chip-select-single');
        for (let i = 0; i < inputEls.length; i++) {
            const input = inputEls[i];
            input.setAttribute('value', String(input.getAttribute('name') === value));
        }
        if (skip !== true) {
            this.setModelValue(value, true);
        }
    }
    get value() {
        const result = this.querySelectorAll('input:checked');
        if (result.length > 0) {
            return result[0].getAttribute('name');
        }
        else {
            return undefined;
        }
    }
    get modelValue() {
        return this._modelValue;
    }
    set modelValue(value) {
        value = this.validateModelValueType(value);
        const modelValueChanged = this.setModelValue(value);
        if (modelValueChanged) {
            if (this.options != null) {
                this.validateWidget();
                if (this.isValid) {
                    this.setError('');
                }
            }
            else {
                //Defer validation until the options have been set.
                this.runValidationOnceOptionsSet = true;
            }
        }
        this.setReadonlyText();
    }
    render() {
        return createElement('fieldset', {}, ...this.renderFieldLabels(), this.renderChips(), this.errorElement, //Note: The order here is expected in redrawCheckboxes()
        this.successElement);
    }
    renderChips() {
        //Make sure we start with an array of some kind, even if empty.
        const options = this.options || [];
        return createElement('div', { attrs: { class: 'neon-chip-select-field-inputs neon-input-field-first' } }, ...options.map((option) => {
            return createElement('neon-2_20_1-chip-select-single', {
                attrs: {
                    id: option.id,
                    'data-label-text': option.labelText,
                    name: option.name,
                    disabled: dynamicAttr(() => {
                        if (elementIsDisabled(this)) {
                            return 'true';
                        }
                        else {
                            return (option.disabled != null ? String(option.disabled) : undefined);
                        }
                    }),
                    'data-tooltip-text': option.dataTooltipText,
                    'data-tooltip-placement': option.dataTooltipPlacement,
                },
                properties: {
                    value: this.modelValue == null ? false : this.modelValue.indexOf(option.name) >= 0
                },
                listeners: {
                    change: (event) => {
                        this.errorPresentWhenBlurOccurred = true;
                        //Note: The reason we pull this out right here, is to keep the values clean when
                        //calling setValue and setModelValue.
                        //we unselect all of the other checkboxes right away.
                        const inputEls = this.querySelectorAll('neon-2_20_1-chip-select-single');
                        for (let i = 0; i < inputEls.length; i++) {
                            const input = inputEls[i];
                            if (input.getAttribute('id') !== option.id) {
                                input.value = false;
                            }
                        }
                        this.inputChange();
                    },
                    blur: (event) => {
                        //In a set timeout so that the new active element will be set.
                        setTimeout(() => {
                            //If the activeElement isn't inside of this widget, then run the focusLost function.
                            if (getClosest(document.activeElement, `[${this.widgetTag}]`) !== this) {
                                this.focusLost(event);
                            }
                        });
                    }
                }
            });
        }));
    }
    redrawChips() {
        replace(this.renderChips(), this.querySelector('.neon-chip-select-field-inputs'));
    }
    //when the attributes change this will run
    attributeChanged(attrName, oldVal, newVal) {
        super.attributeChanged(attrName, oldVal, newVal);
        // attributeChanged is called when attributes listed in "static get observedAttributes()" are changed.
        switch (attrName) {
            case 'disabled':
                updateDynamicAttribute(this, 'disabled');
                break;
        }
    }
    connectedCallback() {
        super.connectedCallback();
        this.i18nUnsubscribe = addTranslationListener(() => {
            updateDynamicText(this);
        });
    }
    disconnectedCallback() {
        if (this.i18nUnsubscribe != null) {
            this.i18nUnsubscribe();
            this.i18nUnsubscribe = undefined;
        }
    }
}
